diff --git a/docs/manual/kinds/cisco_iol.md b/docs/manual/kinds/cisco_iol.md
index 9fffb3c..4539c1e 100644
--- a/docs/manual/kinds/cisco_iol.md
+++ b/docs/manual/kinds/cisco_iol.md
@@ -49,10 +49,24 @@ to connect to a `bash` shell of a running -{{ kind_short_display_name }}- contai

 ```bash
 docker exec -it <container-name/id> bash
 ```

+///
+/// tab | Telnet
+to connect to the -{{ kind_short_display_name }}- console via telnet
+
+```bash
+telnet <container-name/id> 5000
+```
+
+The console is served on the node's management address, so it stays reachable when the IOS management configuration is broken. After the node boots, press Enter first: IOS ignores console input until it receives a lone Enter.
+
+/// warning | Console requires a recent image
+The telnet console requires an -{{ kind_short_display_name }}- image built with srl-labs/vrnetlab after November 2026. Images built from an older vrnetlab revision do not serve a console on port 5000.
+///
+
 ///

 /// note
 Default credentials: `admin:admin`
 ///
diff --git a/nodes/default_node.go b/nodes/default_node.go
index 2469363..fc7acd3 100644
--- a/nodes/default_node.go
+++ b/nodes/default_node.go
@@ -11,10 +11,11 @@ import (
 	"os"
 	"path"
 	"path/filepath"
 	"reflect"
 	"regexp"
+	"slices"
 	"strconv"
 	"strings"
 	"sync"

 	"github.com/charmbracelet/log"
@@ -188,11 +189,11 @@ func (d *DefaultNode) Deploy(ctx context.Context, _ *DeployParams) error {
 	// Set the "CLAB_INTFS" variable to the number of interfaces (endpoints) a node has.
 	// This env var does not count in the eth0 interface that is automatically created by the
 	// container runtime. This env var is used by some containers (e.g. vrnetlab systems) to
 	// postpone the startup until all interfaces
 	// have been added to the container namespace.
-	d.Config().Env[clabconstants.ClabEnvIntfs] = strconv.Itoa(len(d.GetEndpoints()))
+	d.Config().Env[clabconstants.ClabEnvIntfs] = strconv.Itoa(len(d.EndpointsWithParked()))

 	// create the container
 	cID, err := d.Runtime.CreateContainer(ctx, d.Cfg)
 	if err != nil {
 		return err
@@ -1109,10 +1110,17 @@ func (d *DefaultNode) ReleaseEndpoint(e clablinks.Endpoint) error {

 func (d *DefaultNode) GetEndpoints() []clablinks.Endpoint {
 	return d.Endpoints
 }

+func (d *DefaultNode) EndpointsWithParked() []clablinks.Endpoint {
+	if d.parkingNode == nil {
+		return d.Endpoints
+	}
+	return append(slices.Clone(d.Endpoints), d.parkingNode.GetEndpoints()...)
+}
+
 // GetLinkEndpointType returns a veth link endpoint type for default nodes.
 // The LinkEndpointTypeVeth indicates a veth endpoint which doesn't require special handling.
 func (*DefaultNode) GetLinkEndpointType() clablinks.LinkEndpointType {
 	return clablinks.LinkEndpointTypeVeth
 }
diff --git a/nodes/iol/iol.go b/nodes/iol/iol.go
index 5f31e62..54840e7 100644
--- a/nodes/iol/iol.go
+++ b/nodes/iol/iol.go
@@ -226,11 +226,11 @@ func (n *iol) ensureNumSlotsEnv() {
 	}

 	intfIdxRegexp := regexp.MustCompile(`\d+`)
 	needed := n.mgmtSlot + 1

-	for _, ep := range n.Endpoints {
+	for _, ep := range n.EndpointsWithParked() {
 		x, _ := strconv.Atoi(intfIdxRegexp.FindString(ep.GetIfaceName()))
 		if slot, _ := n.iolPortForLinuxIdx(x); slot+1 > needed {
 			needed = slot + 1
 		}
 	}
@@ -336,14 +336,15 @@ func (n *iol) CreateIOLFiles(ctx context.Context) error {
 	if !clabutils.FileExists(path.Join(n.Cfg.LabDir, n.nvramFile)) {
 		// create nvram file
 		clabutils.CreateFile(path.Join(n.Cfg.LabDir, n.nvramFile), "")
 		n.firstBoot = true
 	}
-
 	// create these files so the bind monut doesn't automatically
 	// make folders.
-	clabutils.CreateFile(path.Join(n.Cfg.LabDir, "boot_config.txt"), "")
+	if bootCfg := path.Join(n.Cfg.LabDir, "boot_config.txt"); !clabutils.FileExists(bootCfg) {
+		clabutils.CreateFile(bootCfg, "")
+	}

 	return n.GenInterfaceConfig(ctx)
 }

 // Generate interfaces configuration for IOL (and iouyap/netmap).
@@ -366,11 +367,11 @@ func (n *iol) GenInterfaceConfig(_ context.Context) error {
 	slot, port := 0, 0

 	// Regexp to pull number out of linux'ethX' interface naming
 	IntfRegExpr := regexp.MustCompile(`\d+`)

-	for _, intf := range n.Endpoints {
+	for _, intf := range n.EndpointsWithParked() {
 		// get numeric interface number and cast to int
 		x, _ := strconv.Atoi(IntfRegExpr.FindString(intf.GetIfaceName()))

 		// Interface naming is Ethernet{slot}/{port}. Each slot contains max 4 ports
 		slot, port = n.iolPortForLinuxIdx(x)
diff --git a/nodes/linux/linux.go b/nodes/linux/linux.go
index 020a155..eb7b3aa 100644
--- a/nodes/linux/linux.go
+++ b/nodes/linux/linux.go
@@ -73,11 +73,11 @@ func (n *linux) Init(cfg *clabtypes.NodeConfig, opts ...clabnodes.NodeOption) er

 func (n *linux) Deploy(ctx context.Context, _ *clabnodes.DeployParams) error {
 	// Set the "CLAB_INTFS" variable to the number of interfaces
 	// Which is required by vrnetlab to determine if all configured interfaces are present
 	// such that the internal VM can be started with these interfaces assigned.
-	n.Config().Env[clabconstants.ClabEnvIntfs] = strconv.Itoa(len(n.GetEndpoints()))
+	n.Config().Env[clabconstants.ClabEnvIntfs] = strconv.Itoa(len(n.EndpointsWithParked()))

 	cID, err := n.Runtime.CreateContainer(ctx, n.Cfg)
 	if err != nil {
 		return err
 	}

